<?php require 'config/config.php';require_role(['production']);$page_title='Production';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare('INSERT INTO production_records(production_date,input_kg,output_kg,waste_kg,product_id,notes,recorded_by) VALUES(?,?,?,?,?,?,?)');$s->execute([$_POST['production_date'],$_POST['input_kg'],$_POST['output_kg'],$_POST['waste_kg'],$_POST['product_id']?:null,$_POST['notes'],user()['id']]);log_action('Production recorded','Output '.$_POST['output_kg'].' kg');$msg='Production record saved. Remember to update finished-goods stock through Stock movements.';}$products=$pdo->query('SELECT id,name FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT r.*,p.name,u.name staff FROM production_records r LEFT JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.recorded_by ORDER BY r.id DESC LIMIT 100')->fetchAll();require 'includes/header.php';?><h1>Rice production</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><form method="post"><?php csrf_field();?><div class="formgrid"><div><label>Production date</label><input type="date" name="production_date" value="<?=date('Y-m-d')?>"></div><div><label>Paddy input (kg)</label><input type="number" step=".01" min="0" name="input_kg" required></div><div><label>Rice output (kg)</label><input type="number" step=".01" min="0" name="output_kg" required></div><div><label>Waste / by-product (kg)</label><input type="number" step=".01" min="0" name="waste_kg" value="0"></div><div><label>Finished product</label><select name="product_id"><option value="">Not specified</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div><label>Notes / batch number</label><input name="notes"></div></div><p><button>Save production record</button></p></form></div><div class="panel"><h2>Production history</h2><table><tr><th>Date</th><th>Input kg</th><th>Output kg</th><th>Waste kg</th><th>Product</th><th>Recorded by</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['production_date'])?></td><td><?=e($r['input_kg'])?></td><td><?=e($r['output_kg'])?></td><td><?=e($r['waste_kg'])?></td><td><?=e($r['name'])?></td><td><?=e($r['staff'])?></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';?>